"""Edge-case tests for wasm-renderer-api -- generated by bug-hunter agent."""

from __future__ import annotations

import json

import polars as pl
import pytest

import ferrum as fm
from ferrum._interactive import InteractiveChart, _render_scene
from ferrum.selection import selection_interval, selection_point, value


# ── helpers ──────────────────────────────────────────────────────────────────


def _render(chart: fm.Chart) -> tuple[str, bytes]:
    """Render a chart to (scene_json_str, packed_bytes)."""
    spec, data, viewport, theme, _ = chart._render_inputs()
    from ferrum._core import render_interactive

    return render_interactive(spec, data, viewport=viewport, theme=theme)


# ── 1. Scene JSON: zoom/pan transform fields present ────────────────────────


def test_scene_json_interaction_has_zoom_and_pan_enabled():
    """Scene JSON from a composed chart must include zoom_enabled and
    pan_enabled booleans in the interaction dict -- these drive the
    WASM setTransform / onWheel / onPan / resetZoom entry points."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    left = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=200, height=200)
    right = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=200, height=200)
    composed = left | right
    scene_json, _ = composed._render_interactive()
    scene = json.loads(scene_json)
    interaction = scene["interaction"]
    assert isinstance(interaction["zoom_enabled"], bool), "zoom_enabled must be bool"
    assert isinstance(interaction["pan_enabled"], bool), "pan_enabled must be bool"


# ── 2. Packed data: getTooltip contract for out-of-range indices ─────────────


def test_packed_tooltip_bytes_present_for_large_chart():
    """A chart with >1000 marks with tooltip encoding must have packed
    tooltip bytes in the binary sidecar, so getTooltip can decode them."""
    df = pl.DataFrame(
        {
            "x": list(range(1500)),
            "y": list(range(1500)),
            "label": [f"item_{i}" for i in range(1500)],
        }
    )
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q", tooltip="label:N")
        .properties(width=300, height=200)
    )
    json_str, packed = _render(chart)
    scene = json.loads(json_str)
    assert len(packed) > 0, "packed data must be non-empty for >1000 marks"
    # The packed data encodes instance data + tooltip bytes;
    # we just verify it's substantially larger than instances alone
    # (each CircleInstance is 64 bytes; 1500 * 64 = 96000 bytes minimum)
    assert len(packed) > 96000, (
        f"packed data ({len(packed)} bytes) must include tooltip bytes "
        f"beyond the {1500 * 64} bytes of instance data"
    )


# ── 3. Scene JSON: marks batch structure for packed vs non-packed ────────────


def test_packed_chart_marks_nodes_empty():
    """For charts above the packing threshold, the mark batch's nodes
    array in scene JSON should be empty (data is in the binary sidecar)."""
    df = pl.DataFrame({"x": list(range(1500)), "y": list(range(1500))})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    json_str, packed = _render(chart)
    scene = json.loads(json_str)
    assert len(packed) > 0
    panels = scene["panels"]
    assert len(panels) >= 1
    # Find the point mark batch
    for panel in panels:
        for batch in panel["marks"]:
            if batch.get("kind") == "point":
                nodes = batch.get("nodes", [])
                assert len(nodes) == 0, (
                    f"packed chart mark batch nodes must be empty; got {len(nodes)} nodes"
                )
                return
    # If no point batch found, the test is inconclusive but should not fail


# ── 4. handleClick: scene JSON has data_indices for point selection ──────────


def test_point_selection_chart_has_data_indices_in_marks():
    """A chart with selection_point must have data_indices in each mark
    batch so handleClick can map node_idx to data_idx for the
    Rust interaction state."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0], "g": ["a", "b", "c"]})
    sel = selection_point(fields=["g"], name="test_sel")
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q")
        .add_selection(sel)
        .properties(width=300, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    panel = scene["panels"][0]
    for batch in panel["marks"]:
        if batch.get("kind") == "point":
            data_indices = batch.get("data_indices")
            assert data_indices is not None, (
                "mark batch must have data_indices for point selection hit-testing"
            )
            assert len(data_indices) == 3, f"expected 3 data_indices; got {len(data_indices)}"
            return
    pytest.fail("no point mark batch found in scene")


# ── 5. handleDrag: interval selection spec has correct structure ─────────────


def test_interval_selection_spec_has_translate_zoom_fields():
    """An interval selection spec in scene JSON must have translate and zoom
    boolean fields used by handleDrag to decide whether the brush is
    movable and zoomable."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
    sel = selection_interval(name="iv_test")
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q")
        .add_selection(sel)
        .properties(width=300, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    selections = scene.get("selections", [])
    iv_sels = [s for s in selections if s["type"] == "interval"]
    assert len(iv_sels) >= 1, "must have at least 1 interval selection"
    for s in iv_sels:
        assert "translate" in s, "interval selection must have 'translate' field"
        assert "zoom" in s, "interval selection must have 'zoom' field"


# ── 6. setTransform: tick_levels structure for multi-panel composition ───────


def test_tick_levels_structure_in_composed_scene():
    """A composed chart scene must have tick_levels as a list in
    interaction, with each entry having panel_id plus x_levels/y_levels."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    left = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=200, height=200)
    right = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=200, height=200)
    composed = left | right
    scene_json, _ = composed._render_interactive()
    scene = json.loads(scene_json)
    tick_levels = scene["interaction"]["tick_levels"]
    assert isinstance(tick_levels, list), "tick_levels must be a list"
    # Each entry corresponds to a panel
    for entry in tick_levels:
        assert "panel_id" in entry, "tick_levels entry must have panel_id"
        assert "x_levels" in entry, "tick_levels entry must have x_levels"
        assert "y_levels" in entry, "tick_levels entry must have y_levels"


# ── 7. Single-row DataFrame: scene JSON valid, marks present ─────────────────


def test_single_row_dataframe_interactive():
    """A single-row DataFrame must produce a valid interactive scene with
    exactly 1 mark (circle) in the panel."""
    df = pl.DataFrame({"x": [42.0], "y": [7.0]})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    json_str, packed = _render(chart)
    scene = json.loads(json_str)
    assert len(scene["panels"]) == 1
    panel = scene["panels"][0]
    # Should have at least one mark batch with one node
    point_batches = [b for b in panel["marks"] if b.get("kind") == "point"]
    assert len(point_batches) >= 1, "must have a point mark batch"
    nodes = point_batches[0].get("nodes", [])
    assert len(nodes) == 1, f"single-row DataFrame must produce 1 node; got {len(nodes)}"
    # packed data should be empty (1 mark < 1000 threshold)
    assert len(packed) == 0


# ── 8. Plot area structure for hit testing boundary check ────────────────────


def test_plot_area_has_required_xywh_keys():
    """Each panel's plot_area must have x, y, w, h fields -- these are
    used by hit_test::rect_contains to gate click-inside-plot-area checks."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    for panel in scene["panels"]:
        pa = panel["plot_area"]
        for key in ("x", "y", "w", "h"):
            assert key in pa, f"plot_area missing key {key!r}"
            assert isinstance(pa[key], (int, float)), f"plot_area.{key} must be numeric"
        assert pa["w"] > 0, f"plot_area.w must be positive; got {pa['w']}"
        assert pa["h"] > 0, f"plot_area.h must be positive; got {pa['h']}"


# ── 9. Scene coord structure for zoom routing ────────────────────────────────


def test_scene_panel_coord_is_cartesian():
    """A standard scatter plot panel must have coord type 'cartesian'
    (not 'polar' or 'geo'), which is how onWheel decides between
    Independent and Uniform scale modes."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    panel = scene["panels"][0]
    coord = panel.get("coord", {})
    # The coord uses "kind" field in the serialization format
    coord_kind = coord.get("kind", "").lower()
    assert "cartesian" in coord_kind, (
        f"scatter plot panel coord must be cartesian; got {coord_kind!r}"
    )


# ── 10. NaN in data does not produce NaN in scene positions ──────────────────


def test_nan_in_data_does_not_produce_nan_scene_positions():
    """NaN values in x/y columns must not produce NaN positions in scene
    nodes -- the mark should be dropped or positioned at 0. NaN in SVG
    path d-attributes or circle cx/cy breaks the WASM renderer."""
    df = pl.DataFrame({"x": [1.0, float("nan"), 3.0], "y": [4.0, 5.0, float("nan")]})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    json_str, _ = _render(chart)
    # Check that NaN does not appear as a string in the scene JSON
    assert "NaN" not in json_str, "scene JSON must not contain NaN string"
    # Parse and check circle node positions are finite (not NaN)
    scene = json.loads(json_str)
    for panel in scene["panels"]:
        for batch in panel["marks"]:
            if batch.get("kind") == "point":
                for i, node in enumerate(batch.get("nodes", [])):
                    if node.get("type") == "circle":
                        cx = node.get("cx", 0)
                        cy = node.get("cy", 0)
                        r = node.get("r", 0)
                        assert cx == cx, f"circle {i} cx is NaN"  # NaN != NaN
                        assert cy == cy, f"circle {i} cy is NaN"
                        assert r == r, f"circle {i} r is NaN"


# ── 11. Circle nodes have required cx, cy, r fields ─────────────────────────


def test_circle_nodes_have_required_position_fields():
    """Each circle scene node must have cx, cy, r, and style fields --
    these are required by both the SVG renderer and the WASM hit_test_circles
    function."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    panel = scene["panels"][0]
    for batch in panel["marks"]:
        if batch.get("kind") == "point":
            for i, node in enumerate(batch.get("nodes", [])):
                assert node.get("type") == "circle", f"point mark node {i} must be circle"
                for key in ("cx", "cy", "r"):
                    assert key in node, f"circle node {i} missing {key!r}"
                    assert isinstance(node[key], (int, float)), (
                        f"circle node {i}.{key} must be numeric"
                    )
                assert "style" in node, f"circle node {i} missing 'style'"
            return
    pytest.fail("no point batch found in scene")


# ── 12. Bar chart rect nodes have x, y, w, h ────────────────────────────────


def test_rect_nodes_have_required_position_fields():
    """Each rect scene node must have x, y, w, h fields -- required by
    hit_test_rects for bar-chart tooltip hit-testing."""
    df = pl.DataFrame({"cat": ["a", "b", "c"], "val": [10.0, 20.0, 30.0]})
    chart = fm.Chart(df).mark_bar().encode(x="cat:N", y="val:Q").properties(width=300, height=200)
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    panel = scene["panels"][0]
    for batch in panel["marks"]:
        if batch.get("kind") == "bar":
            nodes = batch.get("nodes", [])
            assert len(nodes) >= 1, "bar chart must have at least 1 rect node"
            for i, node in enumerate(nodes):
                assert node.get("type") == "rect", f"bar node {i} must be rect"
                for key in ("x", "y", "w", "h"):
                    assert key in node, f"rect node {i} missing {key!r}"
            return
    pytest.fail("no bar batch found in scene")


# ── 13. Conditional + interval selection: if_selected/if_not structure ───────


def test_conditional_if_selected_and_if_not_have_value_key():
    """The if_selected and if_not entries in a conditional encoding must
    contain a 'value' key with the actual color/opacity value -- this is
    what the Rust apply_value_to_circle/rect reads."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0], "g": ["a", "b"]})
    sel = selection_point(fields=["g"], name="cond_val_test")
    cond = sel.when(fm.Color("g")).otherwise(value("#aabbcc"))
    chart = (
        fm.Chart(df)
        .mark_point()
        .encode(x="x:Q", y="y:Q")
        .add_selection(sel)
        .conditional(cond)
        .properties(width=300, height=200)
    )
    json_str, _ = _render(chart)
    scene = json.loads(json_str)
    conditionals = scene["interaction"]["conditionals"]
    assert len(conditionals) >= 1
    for c in conditionals:
        if_not = c["if_not"]
        assert "value" in if_not, f"if_not must have 'value' key; got {if_not!r}"


# ── 14. InteractiveChart scene_json round-trip is valid JSON ─────────────────


def test_interactive_chart_scene_json_is_valid_json():
    """InteractiveChart.scene_json must be valid JSON that can be parsed
    and contains the required top-level keys."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    chart = fm.Chart(df).mark_point().encode(x="x:Q", y="y:Q").properties(width=300, height=200)
    ic = InteractiveChart(chart)
    scene = json.loads(ic.scene_json)
    assert "panels" in scene
    assert "width" in scene
    assert "height" in scene
